#include <cstdio>
#include <vector>
#include <limits>
using namespace std;

int main() {
    int n;
    while (scanf("%d", &n), n) {
        vector<int> h(n), r(n);
        for (int i = 0; i < n; ++i) {
            scanf("%d%d", &h[i], &r[i]);
        }

        int M;
        scanf("%d", &M);
        h.resize(n + M);
        r.resize(n + M);
        for (int i = 0; i < M; ++i) {
            scanf("%d%d", &h[n + i], &r[n + i]);
        }

        n += M;
        vector<vector<int>> m(n, vector<int>(n, numeric_limits<int>::max()));

        for (int i = 0; i < n; ++i) {
            m[i][i] = 0; // Distance to self is 0
            for (int j = 0; j < n; ++j) {
                if (h[i] < h[j] && r[i] < r[j]) {
                    m[i][j] = -1; // Mark as reachable
                }
            }
        }

        int ans = numeric_limits<int>::max();
        for (int k = 0; k < n; ++k) {
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    if (m[i][k] != numeric_limits<int>::max() && m[k][j] != numeric_limits<int>::max()) {
                        m[i][j] = min(m[i][j], m[i][k] + m[k][j]);
                    }
                }
            }
        }

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (m[i][j] != numeric_limits<int>::max()) {
                    ans = min(ans, m[i][j]);
                }
            }
        }

        printf("%d\n", -ans + 1);
    }
}

