        data.reserve(n * 2); // Reserve space for both inputs
        for (int i = 0; i < n; ++i) {
            int h, r;
            scanf("%d%d", &h, &r);
            data.emplace_back(h, r); // Add height and radius as a pair
        }

        int M;
        scanf("%d", &M);
        for (int i = 0; i < M; ++i) {
            int h, r;
            scanf("%d%d", &h, &r);
            data.emplace_back(h, r); // Add additional heights and radii
        }

        n += M;
        vector<vector<int>> m(n, vector<int>(n, numeric_limits<int>::max()));

        for (int i = 0; i < n; ++i) {
            m[i][i] = 0; // Initialize the diagonal to 0
            for (int j = 0; j < n; ++j) {
                if (data[i].first < data[j].first && data[i].second < data[j].second) {
                    m[i][j] = -1; // Set edge for valid pairs
                }
            }
        }

        int ans = numeric_limits<int>::max();
        for (int k = 0; k < n; ++k) {
            for (int i = 0; i < n; ++i) {
                if (m[i][k] == numeric_limits<int>::max()) continue; // Skip if no path
                for (int j = 0; j < n; ++j) {
                    if (m[k][j] == numeric_limits<int>::max()) continue; // Skip if no path
                    m[i][j] = min(m[i][j], m[i][k] + m[k][j]);
                    ans = min(ans, m[i][j]);
                }
            }
        }

        printf("%d\n", (ans == numeric_limits<int>::max()) ? -1 : -ans + 1);
    }
}

